function decodeEnvelope(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const ENVELOPE = decodeEnvelope(ENVELOPE_B64);
